export class ImageCache{cache=new Map;maxSize;constructor(maxSize=10){this.maxSize=maxSize}get(key){let value=this.cache.get(key);if(value!==undefined){this.cache.delete(key);this.cache.set(key,value);return value}return}set(key,value){if(this.cache.has(key)){this.cache.delete(key)}else if(this.cache.size>=this.maxSize){let firstKey=this.cache.keys().next().value;if(firstKey!==undefined){this.cache.delete(firstKey)}}this.cache.set(key,value)}clear(){this.cache.clear()}static generateKey(imageBuffer){let view=new Uint8Array(imageBuffer);if(view.length===0)return"0_0";let samples=Math.min(view.length,MAX_KEY_SAMPLES);let last=view.length-1;let hash=0;for(let k=0;k<samples;k++){let index=samples===1?0:Math.round(k*last/(samples-1));hash=(hash<<5)-hash+(view[index]??0);hash=hash&hash}return`${hash}_${view.length}`}}let MAX_KEY_SAMPLES=4096;export let globalImageCache=new ImageCache;export function bypassesCache(options){return Boolean(options?.noCache||options?.dictionary||options?.strategy!==undefined||options?.minimumConfidence!==undefined||options?.spaceRecovery!==undefined||options?.rotateVerticalCrops!==undefined||options?.recBatchSize!==undefined)}